$(document).ready(function(t){$("#stateID").change(function(t){t.preventDefault();var a=$("#stateID").val().split("_"),i=a[0];$.ajax({type:"GET",dataType:"json",url:"/api/city/",data:{state_id:i},success:function(t){200==t.status?($("#cityBox").show(),$.each(t.cityData,function(a,i){$("#cityID").append("<option value='"+t.cityData[a].id+"_"+t.cityData[a].name+"'>"+t.cityData[a].name+"</option>")})):popUpMessage("center",t.msg,t.status)},error:function(t){console.log(t),$("#loginBtn").show()}})}),$("#cityID").change(function(t){var a=$("#cityID").val().split("_"),i=a[0];""!=i?$("#pinCodeBox").show():$("#pinCodeBox").hide()}),$("#addClinic").click(function(t){t.preventDefault(),$("#addClinic").hide(),$.ajax({type:"POST",dataType:"json",data:$("#addNewBuilding").serialize(),success:function(t){console.log("success"),$("#addClinic").show()},error:function(t){console.log(t),$("#addClinic").show()}})})});